import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.InputStream;
import java.util.Set;
import java.util.TreeSet;

public class CF933C_V4 {
    public static final double DELTA = 1e-10;
    static final boolean IS_CODEFORCES = System.getProperty("ONLINE_JUDGE") != null;
    public static Reader input;

    public static void main(String[] args) throws FileNotFoundException {
        if (!IS_CODEFORCES) {
            System.setIn(new FileInputStream("D:\\DataBase\\TESTCASE\\codeforces\\CF933C.in"));
        }
        input = new Reader(System.in);
        run();
    }

    public static void run() {
        int n = input.nextInt();
        Circle[] circles = new Circle[n];

        for (int i = 0; i < n; i++) {
            circles[i] = new Circle(input.nextInt(), input.nextInt(), input.nextInt());
        }

        if (n == 3 && !Circle.intersects(circles[0], circles[1])) {
            int count = 4;
            if (Circle.intersects2(circles[0], circles[2])) {
                count++;
            }
            if (Circle.intersects2(circles[1], circles[2])) {
                count++;
            }
            System.out.println(count);
            return;
        }

        int total = 1;
        TreeSet<Point> points = new TreeSet<>();
        for (int i = 0; i < n; i++) {
            points.clear();
            total++;
            for (int j = 0; j < i; j++) {
                Circle.intersectionPoints(circles[i], circles[j], points);
            }
            if (points.size() >= 2) {
                total += points.size() - 1;
            }
        }

        System.out.println(total);
    }

    public static double euclidean(Point a, Point b) {
        return Math.sqrt(euclideanSq(a, b));
    }

    public static double euclideanSq(Point a, Point b) {
        double dx = a.x - b.x;
        double dy = a.y - b.y;
        return dx * dx + dy * dy;
    }

    public static class Circle {
        Point center;
        int radius;

        public Circle(int x, int y, int r) {
            this.center = new Point(x, y);
            this.radius = r;
        }

        public static boolean intersects(Circle a, Circle b) {
            double d = euclidean(a.center, b.center);
            return d <= a.radius + b.radius + DELTA && d + DELTA >= Math.abs(a.radius - b.radius);
        }

        public static boolean intersects2(Circle a, Circle b) {
            double d = euclidean(a.center, b.center);
            return d < a.radius + b.radius && d > Math.abs(a.radius - b.radius);
        }

        public static void intersectionPoints(Circle a, Circle b, Set<Point> set) {
            if (!intersects(a, b)) {
                return;
            }

            Line segment = new Line(a.center, b.center);
            double d = euclidean(a.center, b.center);
            double distToMid = (d * d - b.radius * b.radius + a.radius * a.radius) / (2 * d);
            Point mid = a.center.move(segment, distToMid);
            Point dir = segment.direction().perp();
            double h = Math.sqrt(a.radius * a.radius - distToMid * distToMid);
            Point p1 = mid.move(dir, h);
            Point p2 = mid.move(dir, -h);

            set.add(p1);
            if (!p2.equals(p1)) {
                set.add(p2);
            }
        }
    }

    public static class Point implements Comparable<Point> {
        double x, y;

        public Point(double x, double y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public String toString() {
            return "(" + x + "," + y + ")";
        }

        public Point minus(Point other) {
            return new Point(x - other.x, y - other.y);
        }

        public Point move(Line line, double dist) {
            return move(line.direction(), dist);
        }

        public Point move(Point vec, double dist) {
            Point unit = vec.normalize();
            return plus(unit.scale(dist));
        }

        public Point plus(Point other) {
            return new Point(x + other.x, y + other.y);
        }

        public Point scale(double factor) {
            return new Point(x * factor, y * factor);
        }

        public Point normalize() {
            double mag = Math.sqrt(x * x + y * y);
            return divide(mag);
        }

        public Point divide(double divisor) {
            return new Point(x / divisor, y / divisor);
        }

        public Point perp() {
            return new Point(-y, x);
        }

        @Override
        public boolean equals(Object obj) {
            Point other = (Point) obj;
            return Math.abs(x - other.x) < DELTA && Math.abs(y - other.y) < DELTA;
        }

        @Override
        public int compareTo(Point o) {
            if (equals(o)) {
                return 0;
            }
            if (Math.abs(x - o.x) < DELTA) {
                return Double.compare(y, o.y);
            }
            return Double.compare(x, o.x);
        }
    }

    public static class Line {
        Point from;
        Point to;

        public Line(Point from, Point to) {
            this.from = from;
            this.to = to;
        }

        public Point direction() {
            return to.minus(from);
        }

        public double length() {
            return euclidean(from, to);
        }
    }

    public static class Reader {
        private final InputStream stream;
        private final byte[] buffer = new byte[4096];
        private int ptr = 0, len = 0;

        public Reader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            while (ptr >= len) {
                try {
                    len = stream.read(buffer);
                } catch (Exception e) {
                }
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() {
            int c = read();
            while (c <= 32) c = read();
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = read();
            }
            int val = 0;
            while (c > 32) {
                val = val * 10 + (c - '0');
                c = read();
            }
            return neg ? -val : val;
        }

        public boolean hasNext() {
            int c = read();
            while (c <= 32) c = read();
            return c != -1;
        }
    }
}
